    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 760 340\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"8\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-red\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"8\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-green\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"8\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 10 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<pattern height=\"8\" id=\"diag-hatch\" patterntransform=\"rotate(45 0 0)\" patternunits=\"userSpaceOnUse\" width=\"8\">\n<line stroke=\"#cbd5e1\" stroke-width=\"1.2\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"8\"></line>\n</pattern>\n</defs>\n<!-- Case 1 (Left): Lifting A端 (B is pivot) -->\n<g transform=\"translate(20, 10)\">\n<!-- Ground -->\n<rect fill=\"url(#diag-hatch)\" height=\"12\" stroke=\"#cbd5e1\" stroke-width=\"1.5\" width=\"320\" x=\"10\" y=\"220\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"2\" x1=\"0\" x2=\"340\" y1=\"220\" y2=\"220\"></line>\n<!-- Rod tilted: B at (290, 220), A at (70, 130). dx = 220, dy = -90. -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"7\" x1=\"70\" x2=\"290\" y1=\"130\" y2=\"220\"></line>\n<!-- Point A -->\n<circle cx=\"70\" cy=\"130\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"800\" x=\"50\" y=\"130\">A</text>\n<!-- Point B (Pivot) -->\n<circle cx=\"290\" cy=\"220\" fill=\"#f59e0b\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"800\" x=\"305\" y=\"225\">B</text>\n<!-- Force F_A = 10 kgw upwards -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"70\" x2=\"70\" y1=\"130\" y2=\"55\"></line>\n<!-- Center of Mass G: closer to B. Let distance from B be x.\n                   Suppose x/L = 10/26 ~ 0.385.\n                   G at: x = 290 - 220*0.385 = 205. y = 220 - 90*0.385 = 185.\n              -->\n<circle cx=\"205\" cy=\"185\" fill=\"#e2e8f0\" r=\"4.5\"></circle>\n<line marker-end=\"url(#arrow-red)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"205\" x2=\"205\" y1=\"185\" y2=\"250\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"700\" x=\"215\" y=\"245\">W (重力)</text>\n<!-- Equation 1 below -->\n<rect fill=\"none\" height=\"40\" rx=\"6\" stroke=\"#cbd5e1\" stroke-width=\"1\" width=\"290\" x=\"25\" y=\"245\"></rect>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" text-anchor=\"middle\" x=\"170\" y=\"270\">10 × 4 = W × x  ⇒  W·x = 40</text>\n</g>\n<!-- Case 2 (Right): Lifting B端 (A is pivot) -->\n<g transform=\"translate(390, 10)\">\n<!-- Ground -->\n<rect fill=\"url(#diag-hatch)\" height=\"12\" stroke=\"#cbd5e1\" stroke-width=\"1.5\" width=\"320\" x=\"10\" y=\"220\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"2\" x1=\"0\" x2=\"340\" y1=\"220\" y2=\"220\"></line>\n<!-- Rod tilted: A at (50, 220), B at (270, 130). dx = 220, dy = -90. -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"7\" x1=\"50\" x2=\"270\" y1=\"220\" y2=\"130\"></line>\n<!-- Point A (Pivot) -->\n<circle cx=\"50\" cy=\"220\" fill=\"#f59e0b\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"800\" x=\"35\" y=\"225\">A</text>\n<!-- Point B -->\n<circle cx=\"270\" cy=\"130\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"800\" x=\"285\" y=\"130\">B</text>\n<!-- Force F_B = 16 kgw upwards -->\n<line marker-end=\"url(#arrow-green)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"270\" x2=\"270\" y1=\"130\" y2=\"55\"></line>\n<!-- Center of Mass G: distance from A is (4 - x) = 4 * (16/26) ~ 2.46.\n                   G at: x = 50 + 220*(1 - 0.385) = 185. y = 220 - 90*(1 - 0.385) = 165.\n              -->\n<circle cx=\"185\" cy=\"165\" fill=\"#e2e8f0\" r=\"4.5\"></circle>\n<line marker-end=\"url(#arrow-red)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"185\" x2=\"185\" y1=\"165\" y2=\"230\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"700\" x=\"195\" y=\"225\">W (重力)</text>\n<!-- Equation 2 below -->\n<rect fill=\"none\" height=\"40\" rx=\"6\" stroke=\"#cbd5e1\" stroke-width=\"1\" width=\"300\" x=\"20\" y=\"245\"></rect>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" text-anchor=\"middle\" x=\"170\" y=\"270\">16 × 4 = W(4 - x) = 4W - 40</text>\n</g>\n<!-- Bottom summary banner -->\n<rect fill=\"none\" height=\"30\" rx=\"6\" stroke=\"#cbd5e1\" stroke-width=\"1\" width=\"400\" x=\"180\" y=\"300\"></rect>\n</svg>",
    "diagrams": [],
    "related": [],
    "answer": "(A)",
