    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 520 280\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<!-- Arrow marker blue -->\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<!-- Arrow marker amber -->\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<!-- Arrow marker emerald -->\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<!-- Ceiling & wall pattern -->\n<pattern height=\"12\" id=\"hatch-ceiling\" patterntransform=\"rotate(45 0 0)\" patternunits=\"userSpaceOnUse\" width=\"12\">\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"12\"></line>\n</pattern>\n</defs>\n<!-- Background subtle rect -->\n<rect fill=\"none\" height=\"100%\" width=\"100%\"></rect>\n<!-- Ceiling & Right Wall Structure -->\n<!-- Ceiling fill -->\n<rect fill=\"url(#hatch-ceiling)\" height=\"25\" opacity=\"0.3\" width=\"410\" x=\"70\" y=\"20\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"70\" x2=\"480\" y1=\"45\" y2=\"45\"></line>\n<!-- Right Wall fill -->\n<rect fill=\"url(#hatch-ceiling)\" height=\"200\" opacity=\"0.3\" width=\"30\" x=\"450\" y=\"45\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"450\" x2=\"450\" y1=\"45\" y2=\"245\"></line>\n<!-- Ceiling hinge support -->\n<rect fill=\"#1e293b\" height=\"15\" rx=\"2\" stroke=\"#38bdf8\" width=\"30\" x=\"110\" y=\"30\"></rect>\n<circle cx=\"125\" cy=\"45\" fill=\"#64748b\" r=\"7\" stroke=\"#cbd5e1\" stroke-width=\"2\"></circle>\n<!-- The uniform rod: length projection dx = 200, dy = 150 (37 deg) -->\n<!-- Rod axis from (125, 45) to (325, 195) -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"125\" x2=\"325\" y1=\"45\" y2=\"195\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"4\" x1=\"125\" x2=\"325\" y1=\"45\" y2=\"195\"></line>\n<!-- Pivot dot at (125, 45) -->\n<circle cx=\"125\" cy=\"45\" fill=\"#e2e8f0\" r=\"4\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"600\" x=\"100\" y=\"65\">樞紐 O</text>\n<!-- Angle 37 deg arc at ceiling -->\n<path d=\"M 175 45 A 50 50 0 0 1 165 75\" fill=\"none\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,2\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"175\" y=\"72\">37°</text>\n<!-- Horizontal rope: from (325, 195) to wall (450, 195) -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"325\" x2=\"450\" y1=\"195\" y2=\"195\"></line>\n<!-- Small wall anchor bracket -->\n<rect fill=\"#cbd5e1\" height=\"10\" width=\"5\" x=\"445\" y=\"190\"></rect>\n<!-- Midpoint Center of Mass (225, 120) -->\n<circle cx=\"225\" cy=\"120\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<!-- Gravity vector W downward -->\n<line marker-end=\"url(#arrow-emerald)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"225\" x2=\"225\" y1=\"120\" y2=\"200\"></line>\n<!-- Tension force arrow T on rod at (325, 195) pointing right -->\n<line marker-end=\"url(#arrow-amber)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"325\" x2=\"400\" y1=\"195\" y2=\"195\"></line>\n<!-- Hinge Force Components & Resultant F at O -->\n<!-- Fx pointing left (opposing T) -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,2\" stroke-width=\"2\" x1=\"125\" x2=\"65\" y1=\"45\" y2=\"45\"></line>\n<!-- Fy pointing up (or downward on ceiling, but ceiling acts UP on rod) -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"3,2\" stroke-width=\"2\" x1=\"125\" x2=\"125\" y1=\"45\" y2=\"0\"></line>\n<!-- Resultant F vector from (125, 45) pointing down-left? Wait: Fy is UP (+y in physical, -y in svg) -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"125\" x2=\"70\" y1=\"45\" y2=\"15\"></line>\n<!-- Dimension / lever arm guides -->\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"4,4\" stroke-width=\"1\" x1=\"125\" x2=\"125\" y1=\"45\" y2=\"245\"></line>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"4,4\" stroke-width=\"1\" x1=\"225\" x2=\"225\" y1=\"120\" y2=\"245\"></line>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"4,4\" stroke-width=\"1\" x1=\"325\" x2=\"325\" y1=\"195\" y2=\"245\"></line>\n<!-- Horizontal arms at bottom -->\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"125\" x2=\"225\" y1=\"235\" y2=\"235\"></line>\n<!-- Vertical arm for T on the left/right -->\n<line opacity=\"0.5\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"125\" x2=\"125\" y1=\"45\" y2=\"195\"></line>\n<line opacity=\"0.5\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"325\" x2=\"125\" y1=\"195\" y2=\"195\"></line>\n</svg>",
