    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 520 330\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-purple\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n</defs>\n<!-- Vertical Plumb Line (鉛垂線) -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"6,4\" stroke-width=\"1.8\" x1=\"260\" x2=\"260\" y1=\"20\" y2=\"305\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"bold\" x=\"240\" y=\"322\">鉛垂線</text>\n<!-- Inclined Rod: angle theta ~ 28 deg with vertical -->\n<!-- Nail pivot at (260, 115) -->\n<!-- Top end at (295, 45): arm = 25 cm -->\n<!-- Midpoint CG at (225, 185): arm = 25 cm from nail (50 cm from top) -->\n<!-- Bottom end at (155, 325): arm = 75 cm from nail (100 cm total) -->\n<!-- Rod body -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"160\" x2=\"295\" y1=\"315\" y2=\"45\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"3.5\" x1=\"160\" x2=\"295\" y1=\"315\" y2=\"45\"></line>\n<!-- Nail pivot dot -->\n<circle cx=\"260\" cy=\"115\" fill=\"#f59e0b\" r=\"6\" stroke=\"#ffffff\" stroke-width=\"2\"></circle>\n<!-- Angle theta arc at nail between rod and plumb line -->\n<path d=\"M 260 150 A 35 35 0 0 1 244 146\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"bold\" x=\"245\" y=\"140\">θ</text>\n<!-- Force F at top (295, 45) horizontal pointing right -->\n<line marker-end=\"url(#arrow-purple)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"295\" x2=\"385\" y1=\"45\" y2=\"45\"></line>\n<!-- Center of Mass (重心) at (225, 185) -->\n<circle cx=\"225\" cy=\"185\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<!-- Gravity W at CG pointing down -->\n<line marker-end=\"url(#arrow-emerald)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"225\" x2=\"225\" y1=\"185\" y2=\"265\"></line>\n<!-- Nail Reaction Force Components at (260, 115) -->\n<!-- Rx to left = F -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"2\" x1=\"260\" x2=\"190\" y1=\"115\" y2=\"115\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"175\" y=\"105\">R_x = F</text>\n<!-- Ry upward = W -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"2\" x1=\"260\" x2=\"260\" y1=\"115\" y2=\"45\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"220\" y=\"75\">R_y = W</text>\n<!-- Resultant R vector -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2.8\" x1=\"260\" x2=\"190\" y1=\"115\" y2=\"45\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"bold\" x=\"160\" y=\"45\">R (釘子力)</text>\n<!-- Arm annotations -->\n<!-- Top segment 25 cm -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"295\" x2=\"260\" y1=\"45\" y2=\"45\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"11\" x=\"290\" y=\"90\">25 cm</text>\n<!-- CG segment 25 cm -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"225\" x2=\"260\" y1=\"185\" y2=\"185\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"11\" x=\"225\" y=\"135\">25 cm</text>\n</svg>",
