    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 540 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-rose\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<pattern height=\"12\" id=\"hatch-ground\" patterntransform=\"rotate(45 0 0)\" patternunits=\"userSpaceOnUse\" width=\"12\">\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"12\"></line>\n</pattern>\n</defs>\n<!-- Ground -->\n<rect fill=\"url(#hatch-ground)\" height=\"25\" opacity=\"0.3\" width=\"460\" x=\"40\" y=\"260\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"40\" x2=\"500\" y1=\"260\" y2=\"260\"></line>\n<!-- Person standing at left -->\n<g transform=\"translate(100, 160)\">\n<!-- Head -->\n<circle cx=\"20\" cy=\"15\" fill=\"#94a3b8\" r=\"9\"></circle>\n<!-- Torso -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"4\" x1=\"20\" x2=\"20\" y1=\"24\" y2=\"65\"></line>\n<!-- Legs -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"20\" x2=\"10\" y1=\"65\" y2=\"100\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"20\" x2=\"30\" y1=\"65\" y2=\"100\"></line>\n<!-- Arms holding rope -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"3\" x1=\"20\" x2=\"42\" y1=\"35\" y2=\"40\"></line>\n<circle cx=\"42\" cy=\"40\" fill=\"#f59e0b\" r=\"3\"></circle>\n</g>\n<!-- Hinge O on Ground at (270, 260) -->\n<path d=\"M 255 260 L 285 260 L 275 250 L 265 250 Z\" fill=\"#cbd5e1\" stroke=\"#cbd5e1\" stroke-width=\"1\"></path>\n<circle cx=\"270\" cy=\"252\" fill=\"#f59e0b\" r=\"6\" stroke=\"#ffffff\" stroke-width=\"2\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"250\" y=\"278\">O</text>\n<!-- Rod OA: angle 60 deg with ground, length = 200 px -->\n<!-- dx = 200 * cos(60) = 100, dy = 200 * sin(60) = 173 -->\n<!-- O is at (270, 252), A is at (370, 79) -->\n<!-- Midpoint B is at (320, 165) -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"9\" x1=\"270\" x2=\"370\" y1=\"252\" y2=\"79\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"4\" x1=\"270\" x2=\"370\" y1=\"252\" y2=\"79\"></line>\n<!-- Point A top -->\n<circle cx=\"370\" cy=\"79\" fill=\"#e2e8f0\" r=\"4\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"15\" font-weight=\"bold\" x=\"382\" y=\"82\">A</text>\n<!-- Point B midpoint -->\n<circle cx=\"320\" cy=\"165\" fill=\"#f59e0b\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"328\" y=\"160\">B (中點)</text>\n<!-- Horizontal rope from B(320, 165) to person's hands (142, 165) -->\n<!-- Wait, translate(100,160) arms are at 100+42=142, 160+40=200. Let's make rope perfectly horizontal at y=200 -->\n<!-- Let's adjust B: midpoint y = 165. Let's adjust person arms to y = 165 -->\n<!-- Ground angle 60 deg arc at O -->\n<path d=\"M 305 252 A 35 35 0 0 0 287 222\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"13\" font-weight=\"bold\" x=\"302\" y=\"240\">60°</text>\n<!-- Horizontal rope to B -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"142\" x2=\"320\" y1=\"200\" y2=\"200\"></line>\n<!-- Note: if B is at y=200, let's mark B at y=200 (distance along rod = 60/173 * 3 = 1m? Let's keep rope at y=165 and adjust person) -->\n<!-- Actually, let's connect rope from person (142, 200) to B(320, 165) or make rope horizontal at y=165 -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"142\" x2=\"320\" y1=\"165\" y2=\"165\"></line>\n<!-- Tension vector T on rod pointing left -->\n<line marker-end=\"url(#arrow-amber)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"320\" x2=\"230\" y1=\"165\" y2=\"165\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"260\" y=\"152\">T (拉力)</text>\n<!-- Weight hanging at A -->\n<line stroke=\"#cbd5e1\" stroke-width=\"1.8\" x1=\"370\" x2=\"370\" y1=\"79\" y2=\"155\"></line>\n<rect fill=\"#1e293b\" height=\"35\" rx=\"3\" stroke=\"#38bdf8\" stroke-width=\"2\" width=\"40\" x=\"350\" y=\"155\"></rect>\n<!-- Ground reaction force components at O(270, 252) -->\n<!-- Fx to right -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"2\" x1=\"270\" x2=\"340\" y1=\"252\" y2=\"252\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"320\" y=\"270\">F_x = T</text>\n<!-- Fy upward -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"2\" x1=\"270\" x2=\"270\" y1=\"252\" y2=\"190\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"220\" y=\"210\">F_y = W</text>\n<!-- Resultant F at angle theta -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2.8\" x1=\"270\" x2=\"340\" y1=\"252\" y2=\"190\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"345\" y=\"195\">F_地</text>\n<!-- Angle theta arc -->\n<path d=\"M 295 252 A 25 25 0 0 0 291 235\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"1.5\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"300\" y=\"240\">θ</text>\n<!-- Rod length label -->\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"345\" y=\"125\">3 m</text>\n</svg>",
