    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 520 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-rose\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n</defs>\n<!-- Plumb Line from O(220, 50) vertically down -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"5,4\" stroke-width=\"1.8\" x1=\"220\" x2=\"220\" y1=\"50\" y2=\"290\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"175\" y=\"285\">鉛垂基準線</text>\n<!-- Pivot O -->\n<circle cx=\"220\" cy=\"50\" fill=\"#475569\" r=\"7\" stroke=\"#cbd5e1\" stroke-width=\"2\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"16\" font-weight=\"bold\" x=\"200\" y=\"45\">O</text>\n<!-- Inclined Rod OP: angle theta ~ 30 deg with vertical -->\n<!-- Length = 220 px -->\n<!-- dx = 220 * sin(30) = 110, dy = 220 * cos(30) = 190.5 -->\n<!-- P = (330, 240.5) -->\n<!-- Midpoint CG = (275, 145.2) -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"220\" x2=\"330\" y1=\"50\" y2=\"241\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"4\" x1=\"220\" x2=\"330\" y1=\"50\" y2=\"241\"></line>\n<!-- Point P at end -->\n<circle cx=\"330\" cy=\"241\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<!-- Angle theta arc at O -->\n<path d=\"M 220 105 A 55 55 0 0 0 248 98\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"232\" y=\"125\">θ</text>\n<!-- Horizontal Force F at P -->\n<line marker-end=\"url(#arrow-rose)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"330\" x2=\"440\" y1=\"241\" y2=\"241\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"16\" font-weight=\"bold\" x=\"400\" y=\"230\">水平拉力 F</text>\n<!-- Midpoint Center of Mass -->\n<circle cx=\"275\" cy=\"145\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<line marker-end=\"url(#arrow-emerald)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"275\" x2=\"275\" y1=\"145\" y2=\"225\"></line>\n<!-- Vertical lever arm for F: l cos theta -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"220\" x2=\"160\" y1=\"50\" y2=\"50\"></line>\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"330\" x2=\"160\" y1=\"241\" y2=\"241\"></line>\n<line marker-end=\"url(#arrow-blue)\" marker-start=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2\" x1=\"170\" x2=\"170\" y1=\"50\" y2=\"241\"></line>\n<!-- Horizontal lever arm for W: (l/2) sin theta -->\n<line marker-end=\"url(#arrow-emerald)\" marker-start=\"url(#arrow-emerald)\" stroke=\"#cbd5e1\" stroke-width=\"2\" x1=\"220\" x2=\"275\" y1=\"260\" y2=\"260\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"220\" y=\"280\">½ ℓ sinθ</text>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"275\" x2=\"275\" y1=\"145\" y2=\"260\"></line>\n</svg>",
