    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 520 300\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<pattern height=\"10\" id=\"hatch-ceiling\" patterntransform=\"rotate(45 0 0)\" patternunits=\"userSpaceOnUse\" width=\"10\">\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"10\"></line>\n</pattern>\n</defs>\n<!-- Top Ceiling -->\n<rect fill=\"url(#hatch-ceiling)\" height=\"20\" opacity=\"0.3\" width=\"200\" x=\"250\" y=\"25\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"250\" x2=\"450\" y1=\"45\" y2=\"45\"></line>\n<!-- Bottom Smooth Ground -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"80\" x2=\"440\" y1=\"240\" y2=\"240\"></line>\n<!-- Vertical Hanging String from Ceiling (370, 45) to Rod Top (370, 100) -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"370\" x2=\"370\" y1=\"45\" y2=\"100\"></line>\n<circle cx=\"370\" cy=\"45\" fill=\"#94a3b8\" r=\"3\"></circle>\n<circle cx=\"370\" cy=\"100\" fill=\"#f59e0b\" r=\"4\"></circle>\n<!-- Tension Vector T upward -->\n<line marker-end=\"url(#arrow-amber)\" stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"370\" x2=\"370\" y1=\"100\" y2=\"55\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"16\" font-weight=\"bold\" x=\"382\" y=\"75\">T (繩張力)</text>\n<!-- Inclined Rod from (230, 240) to (370, 100) -->\n<!-- dx = 140, dy = 140 (45 deg!) -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"10\" x1=\"230\" x2=\"370\" y1=\"240\" y2=\"100\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"4\" x1=\"230\" x2=\"370\" y1=\"240\" y2=\"100\"></line>\n<!-- Ground Contact Point -->\n<circle cx=\"230\" cy=\"240\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"210\" y=\"255\">O</text>\n<!-- Normal Force N from ground upward -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"230\" x2=\"230\" y1=\"240\" y2=\"175\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"240\" y=\"190\">N = W/2</text>\n<!-- Angle 45 deg arc -->\n<path d=\"M 270 240 A 40 40 0 0 0 258 212\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"275\" y=\"230\">45°</text>\n<!-- Midpoint Center of Mass (300, 170) -->\n<circle cx=\"300\" cy=\"170\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<line marker-end=\"url(#arrow-emerald)\" stroke=\"#cbd5e1\" stroke-width=\"2.5\" x1=\"300\" x2=\"300\" y1=\"170\" y2=\"235\"></line>\n<!-- Horizontal projection helper lines -->\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"230\" x2=\"230\" y1=\"240\" y2=\"280\"></line>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"300\" x2=\"300\" y1=\"170\" y2=\"280\"></line>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"3,3\" stroke-width=\"1\" x1=\"370\" x2=\"370\" y1=\"100\" y2=\"280\"></line>\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"230\" x2=\"300\" y1=\"275\" y2=\"275\"></line>\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"230\" x2=\"370\" y1=\"275\" y2=\"275\"></line>\n</svg>",
