    "svg": "<svg class=\"exam-diagram-svg\" style=\"max-width: 580px; width: 100%; height: auto;\" viewbox=\"0 0 520 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<marker id=\"arrow-blue\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-amber\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<marker id=\"arrow-emerald\" markerheight=\"6\" markerwidth=\"6\" orient=\"auto-start-reverse\" refx=\"7\" refy=\"5\" viewbox=\"0 0 10 10\">\n<path d=\"M 0 1 L 9 5 L 0 9 z\" fill=\"#cbd5e1\"></path>\n</marker>\n<pattern height=\"10\" id=\"hatch-wall\" patterntransform=\"rotate(45 0 0)\" patternunits=\"userSpaceOnUse\" width=\"10\">\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"0\" x2=\"0\" y1=\"0\" y2=\"10\"></line>\n</pattern>\n</defs>\n<!-- Right Vertical Smooth Wall -->\n<rect fill=\"url(#hatch-wall)\" height=\"250\" opacity=\"0.3\" width=\"20\" x=\"420\" y=\"30\"></rect>\n<line stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"420\" x2=\"420\" y1=\"30\" y2=\"280\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"12\" x=\"430\" y=\"20\">光滑垂直牆</text>\n<!-- Bottom Ground -->\n<line stroke=\"#cbd5e1\" stroke-width=\"3\" x1=\"80\" x2=\"440\" y1=\"280\" y2=\"280\"></line>\n<rect fill=\"url(#hatch-wall)\" height=\"20\" opacity=\"0.2\" width=\"360\" x=\"80\" y=\"280\"></rect>\n<!-- Inclined Rod: Ground at (160, 280), Wall top at (420, 50) -->\n<!-- dx = 260, dy = 230 -->\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"8\" x1=\"160\" x2=\"420\" y1=\"280\" y2=\"50\"></line>\n<line stroke=\"#cbd5e1\" stroke-linecap=\"round\" stroke-width=\"3.5\" x1=\"160\" x2=\"420\" y1=\"280\" y2=\"50\"></line>\n<!-- Ground Contact Point (參考點 O) -->\n<circle cx=\"160\" cy=\"280\" fill=\"#f59e0b\" r=\"5\"></circle>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"110\" y=\"295\">接觸參考點 O</text>\n<!-- Wall Contact Point (420, 50) -->\n<circle cx=\"420\" cy=\"50\" fill=\"#e2e8f0\" r=\"4\"></circle>\n<!-- Wall Normal Force N pointing left -->\n<line marker-end=\"url(#arrow-blue)\" stroke=\"#cbd5e1\" stroke-width=\"2.8\" x1=\"420\" x2=\"330\" y1=\"50\" y2=\"50\"></line>\n<!-- Hanging Point: L/3 from top, 2/3 L from bottom -->\n<!-- x = 160 + (2/3)*260 = 160 + 173.3 = 333.3 -->\n<!-- y = 280 - (2/3)*230 = 280 - 153.3 = 126.7 -->\n<circle cx=\"333\" cy=\"127\" fill=\"#e2e8f0\" r=\"5\"></circle>\n<!-- Top L/3 dimension marker -->\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"420\" x2=\"440\" y1=\"50\" y2=\"50\"></line>\n<line stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"333\" x2=\"440\" y1=\"127\" y2=\"127\"></line>\n<line stroke=\"#cbd5e1\" stroke-width=\"1.5\" x1=\"435\" x2=\"435\" y1=\"50\" y2=\"127\"></line>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"390\" y=\"95\">L / 3</text>\n<!-- Hanging Weight W -->\n<line stroke=\"#cbd5e1\" stroke-width=\"2\" x1=\"333\" x2=\"333\" y1=\"127\" y2=\"200\"></line>\n<rect fill=\"#1e293b\" height=\"28\" rx=\"3\" stroke=\"#38bdf8\" stroke-width=\"2\" width=\"30\" x=\"318\" y=\"200\"></rect>\n<!-- Angle theta with ground -->\n<path d=\"M 210 280 A 50 50 0 0 0 200 245\" fill=\"none\" stroke=\"#cbd5e1\" stroke-width=\"2\"></path>\n<text fill=\"#f1f5f9\" font-family=\"inherit\" font-size=\"14\" font-weight=\"bold\" x=\"215\" y=\"270\">θ</text>\n<!-- Horizontal arm for W from O -->\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"160\" x2=\"160\" y1=\"280\" y2=\"305\"></line>\n<line opacity=\"0.4\" stroke=\"#cbd5e1\" stroke-dasharray=\"2,2\" stroke-width=\"1\" x1=\"333\" x2=\"333\" y1=\"200\" y2=\"305\"></line>\n<line stroke=\"#cbd5e1\" stroke-width=\"1.8\" x1=\"160\" x2=\"333\" y1=\"300\" y2=\"300\"></line>\n</svg>",
